#include <stdio.h>
void foo(int *p, int x){ *p=x; }
int main(){ int *z; int a=20, b=25; z=&a; foo(z,b); printf("%d",a); return 0; }
The output of the given C program is __________.

#include <stdio.h>
int foo(int S[],int size){ if(size==0) return 0; if(size==1) return 1; if(S[0]!=S[1]) return 1+foo(S+1,size-1); return foo(S+1,size-1); }
int main(){ int A[]={0,1,2,2,2,0,0,1,1}; printf("%d",foo(A,9)); return 0; }
The value printed by the given C program is _______.
